import{_ as o,a as s,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · 单元 3 复习与自测 · 第49–55课","description":"L49–L72 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 3 复习与自测 · 第49–55课","description":"L49–L72 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-03/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 3 复习与自测","summary":"L49–L72 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 3 复习与自测","link":"/life/english/new-concept/book-1/unit-03/review"},"next":{"text":"第一册：英语初阶 · 单元 3 复习与自测 · 第56–62课","link":"/life/english/new-concept/book-1/unit-03/review-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 3 复习与自测","link":"/life/english/new-concept/book-1/unit-03/review"},"next":{"text":"第一册：英语初阶 · 单元 3 复习与自测 · 第56–62课","link":"/life/english/new-concept/book-1/unit-03/review-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-03/review-part-01.md","filePath":"life/english/new-concept/book-1/unit-03/review-part-01.md"}'),r={name:"life/english/new-concept/book-1/unit-03/review-part-01.md"};function t(i,e,l,c,h,p){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-单元-3-复习与自测-·-第49–55课" tabindex="-1">第一册：英语初阶 · 单元 3 复习与自测 · 第49–55课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-3-复习与自测-·-第49–55课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 3 复习与自测 · 第49–55课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-03/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="第一册-英语初阶-·-单元-3-复习与自测" tabindex="-1">第一册：英语初阶 · 单元 3 复习与自测 <a class="header-anchor" href="#第一册-英语初阶-·-单元-3-复习与自测" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 3 复习与自测 {#第一册-英语初阶-·-单元-3-复习与自测}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-1/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-49-·-第三人称单数与-does" tabindex="-1">Lesson 49 · 第三人称单数与 does <a class="header-anchor" href="#lesson-49-·-第三人称单数与-does" aria-label="Permalink to &quot;Lesson 49 · 第三人称单数与 does {#lesson-49-·-第三人称单数与-does}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My brother prefers fish to beef.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1 {#练习-1}&quot;">​</a></h3><p>填动词：My brother ___ (prefer) fish.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> prefers</p><p><strong>解析：</strong> 按本课规则判断：一般现在时主语为 he/she/it 或单个姓名时，肯定句实义动词通常加 s/es。变疑问或否定时由 does 承担人称变化，后面动词恢复原形：Does she like ...? / She doesn&#39;t like ...。不能同时让 does 和 likes 都标记第三人称。meat 通常是不可数名词，谈一类肉不用复数。</p></details><p><strong>表达迁移：</strong> 围绕“购买食物时表达家人的喜好”写两至三句，再读给同伴听。至少使用一次第三人称单数与 does，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My brother prefers fish to beef. Does your daughter eat carrots?</p><p>My brother 是单数主语，prefer 加 s；prefer A to B 表示在两者之间偏爱 A，to 不是不定式标记。 Does 标记第三人称疑问，your daughter 为主语，eat 恢复原形；carrots 作泛指食物，不加冠词。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-049">回看本课</a></p><h2 id="lesson-50-·-第三人称单数与-does" tabindex="-1">Lesson 50 · 第三人称单数与 does <a class="header-anchor" href="#lesson-50-·-第三人称单数与-does" aria-label="Permalink to &quot;Lesson 50 · 第三人称单数与 does {#lesson-50-·-第三人称单数与-does}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Does your daughter eat carrots?</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1 {#练习-1-1}&quot;">​</a></h3><p>填原形：Does she ___ (eat) carrots?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> eat</p><p><strong>解析：</strong> 按本课规则判断：一般现在时主语为 he/she/it 或单个姓名时，肯定句实义动词通常加 s/es。变疑问或否定时由 does 承担人称变化，后面动词恢复原形：Does she like ...? / She doesn&#39;t like ...。不能同时让 does 和 likes 都标记第三人称。meat 通常是不可数名词，谈一类肉不用复数。</p></details><p><strong>表达迁移：</strong> 围绕“购买食物时表达家人的喜好”写两至三句，再读给同伴听。至少使用一次第三人称单数与 does，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Does your daughter eat carrots? My brother prefers fish to beef.</p><p>Does 标记第三人称疑问，your daughter 为主语，eat 恢复原形；carrots 作泛指食物，不加冠词。 My brother 是单数主语，prefer 加 s；prefer A to B 表示在两者之间偏爱 A，to 不是不定式标记。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-050">回看本课</a></p><h2 id="lesson-51-·-come-from-与国籍表达" tabindex="-1">Lesson 51 · come from 与国籍表达 <a class="header-anchor" href="#lesson-51-·-come-from-与国籍表达" aria-label="Permalink to &quot;Lesson 51 · come from 与国籍表达 {#lesson-51-·-come-from-与国籍表达}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My neighbours come from Portugal.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1 {#练习-1-2}&quot;">​</a></h3><p>补助动词：Where ___ your neighbours come from?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> do</p><p><strong>解析：</strong> 按本课规则判断：come from 是实义动词结构，一般现在时问句用 do/does；be from 用 be 提问。Where do you come from? 与 Where are you from? 都可询问来源，但不能混成 Where are you come from?。描述气候常用一般现在时，it 可作天气主语；sunny 等形容词与 rains 等动词结构要区分。</p></details><p><strong>表达迁移：</strong> 围绕“谈论国家与典型气候”写两至三句，再读给同伴听。至少使用一次come from 与国籍表达，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My neighbours come from Portugal. It is often windy here in spring.</p><p>My neighbours 是复数主语，come 不加 s；from Portugal 是来源信息，不能把 come 换成 are come。 It 是天气主语；is 后放频率副词 often，windy 为表语。in spring 说明季节，不用 on。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-051">回看本课</a></p><h2 id="lesson-52-·-come-from-与国籍表达" tabindex="-1">Lesson 52 · come from 与国籍表达 <a class="header-anchor" href="#lesson-52-·-come-from-与国籍表达" aria-label="Permalink to &quot;Lesson 52 · come from 与国籍表达 {#lesson-52-·-come-from-与国籍表达}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> It is often windy here in spring.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1 {#练习-1-3}&quot;">​</a></h3><p>补 be：It ___ often windy.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：come from 是实义动词结构，一般现在时问句用 do/does；be from 用 be 提问。Where do you come from? 与 Where are you from? 都可询问来源，但不能混成 Where are you come from?。描述气候常用一般现在时，it 可作天气主语；sunny 等形容词与 rains 等动词结构要区分。</p></details><p><strong>表达迁移：</strong> 围绕“谈论国家与典型气候”写两至三句，再读给同伴听。至少使用一次come from 与国籍表达，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>It is often windy here in spring. My neighbours come from Portugal.</p><p>It 是天气主语；is 后放频率副词 often，windy 为表语。in spring 说明季节，不用 on。 My neighbours 是复数主语，come 不加 s；from Portugal 是来源信息，不能把 come 换成 are come。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-052">回看本课</a></p><h2 id="lesson-53-·-频率副词与天气动词" tabindex="-1">Lesson 53 · 频率副词与天气动词 <a class="header-anchor" href="#lesson-53-·-频率副词与天气动词" aria-label="Permalink to &quot;Lesson 53 · 频率副词与天气动词 {#lesson-53-·-频率副词与天气动词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> It often rains in this coastal town.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1 {#练习-1-4}&quot;">​</a></h3><p>选择 rain/rains：It often ___ here.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> rains</p><p><strong>解析：</strong> 按本课规则判断：always、usually、often、sometimes、never 表频率，通常位于实义动词前、be 后。It often rains 中 rain 是动词；It is often rainy 中 rainy 是形容词。频率不等于眼前进行：often rains 描述规律，is raining 描述此刻。never 已含否定意义，在标准英语中通常不再配 don&#39;t。</p></details><p><strong>表达迁移：</strong> 围绕“比较季节天气并询问来自哪里”写两至三句，再读给同伴听。至少使用一次频率副词与天气动词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>It often rains in this coastal town. The evenings are usually cool in autumn.</p><p>It 是天气主语，rains 是实义动词第三人称形式；often 在实义动词之前，in this coastal town 是地点。 The evenings 是复数主语，are 后放 usually，cool 作表语；in autumn 表季节。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-053">回看本课</a></p><h2 id="lesson-54-·-频率副词与天气动词" tabindex="-1">Lesson 54 · 频率副词与天气动词 <a class="header-anchor" href="#lesson-54-·-频率副词与天气动词" aria-label="Permalink to &quot;Lesson 54 · 频率副词与天气动词 {#lesson-54-·-频率副词与天气动词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The evenings are usually cool in autumn.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1 {#练习-1-5}&quot;">​</a></h3><p>给 usually 排序：The evenings / are / cool / usually.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The evenings are usually cool.</p><p><strong>解析：</strong> 按本课规则判断：always、usually、often、sometimes、never 表频率，通常位于实义动词前、be 后。It often rains 中 rain 是动词；It is often rainy 中 rainy 是形容词。频率不等于眼前进行：often rains 描述规律，is raining 描述此刻。never 已含否定意义，在标准英语中通常不再配 don&#39;t。</p></details><p><strong>表达迁移：</strong> 围绕“比较季节天气并询问来自哪里”写两至三句，再读给同伴听。至少使用一次频率副词与天气动词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The evenings are usually cool in autumn. It often rains in this coastal town.</p><p>The evenings 是复数主语，are 后放 usually，cool 作表语；in autumn 表季节。 It 是天气主语，rains 是实义动词第三人称形式；often 在实义动词之前，in this coastal town 是地点。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-054">回看本课</a></p><h2 id="lesson-55-·-一般现在时的习惯动作" tabindex="-1">Lesson 55 · 一般现在时的习惯动作 <a class="header-anchor" href="#lesson-55-·-一般现在时的习惯动作" aria-label="Permalink to &quot;Lesson 55 · 一般现在时的习惯动作 {#lesson-55-·-一般现在时的习惯动作}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My father leaves home at half past seven.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1 {#练习-1-6}&quot;">​</a></h3><p>填动词：My father ___ (leave) home early.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> leaves</p><p><strong>解析：</strong> 按本课规则判断：一般现在时描述习惯、规律和相对稳定状态。谈家庭成员时要逐个检查主语：parents 用 go，father 用 goes。时间表达可用 at seven、in the evening、on Mondays。通常活动不必加 now，now 更容易指向正在进行。every day 是时间短语，everyday 是形容词，修饰日常事物。</p></details><p><strong>表达迁移：</strong> 围绕“介绍一家人的每日作息”写两至三句，再读给同伴听。至少使用一次一般现在时的习惯动作，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My father leaves home at half past seven. We usually cook dinner together.</p><p>My father 为第三人称单数，所以用 leaves；home 在 leave home 中表示离开家，at half past seven 表钟点。 We 为复数主语，cook 用原形；usually 放在实义动词前，together 表示一起完成动作。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-055">回看本课</a></p>',63)])])}const d=o(r,[["render",t]]);export{u as __pageData,d as default};
